import {useMemo, useState} from 'react'
import type {UploadCallbacks, UploadConfig, UploadState} from '@github-ui/batch-upload'
import {FileAttachment, type FileAttachmentProps} from '@github-ui/file-attachment'
import type {Attachment} from '@github-ui/file-attachment/attachment'
import {completedTagText, placeholderText, replacementText} from '@github-ui/upload-markdown-image'

export interface EditorUploadEvent {
  state: 'uploading' | 'uploaded' | 'failed'
  placeholder: string
  replacementText: string
}

export interface FileAttachmentEditorProps extends Omit<FileAttachmentProps, 'uploadConfig' | 'uploadCallbacks'> {
  /** Upload policy URL for the batch upload endpoint. */
  policyUrl: string
  /** CSRF token for upload policy requests. */
  csrfToken: string
  /** Repository ID used in upload policy. */
  repositoryId?: string
  /** Upload container type (e.g. 'blob'). */
  uploadContainerType?: string
  /** Upload container ID. */
  uploadContainerId?: string
  /** Called when the editor should insert/replace/remove upload placeholder text. */
  onEditorUpload: (event: EditorUploadEvent) => void
  /** Called when the upload state changes (for driving UI like error messages). */
  onUploadStateChange: (state: UploadState, message?: string) => void
}

export function FileAttachmentEditor({
  policyUrl,
  csrfToken,
  repositoryId,
  uploadContainerType,
  uploadContainerId,
  onEditorUpload,
  onUploadStateChange,
  ...rest
}: FileAttachmentEditorProps) {
  const [uploadState, setUploadState] = useState<UploadState>('is-default')

  const uploadConfig: UploadConfig = useMemo(
    () => ({
      policyUrl,
      csrfToken,
      repositoryId,
      uploadContainerType,
      uploadContainerId,
    }),
    [policyUrl, csrfToken, repositoryId, uploadContainerType, uploadContainerId],
  )

  const uploadCallbacks: UploadCallbacks = useMemo(
    () => ({
      onStateChange(state: UploadState, message?: string) {
        setUploadState(state)
        onUploadStateChange(state, message)
      },
      onSetup(_batch, attachment: Attachment) {
        onEditorUpload({
          state: 'uploading',
          placeholder: placeholderText(attachment),
          replacementText: replacementText(attachment),
        })
      },
      async onComplete(_batch, attachment: Attachment) {
        const tagText = await completedTagText(attachment)
        onEditorUpload({
          state: 'uploaded',
          placeholder: placeholderText(attachment),
          replacementText: tagText,
        })
      },
      onError(_batch, attachment: Attachment) {
        onEditorUpload({
          state: 'failed',
          placeholder: placeholderText(attachment),
          replacementText: '',
        })
      },
      onInvalid(_batch, attachment: Attachment) {
        onEditorUpload({
          state: 'failed',
          placeholder: placeholderText(attachment),
          replacementText: '',
        })
      },
    }),
    [onEditorUpload, onUploadStateChange],
  )

  return (
    <FileAttachment
      {...rest}
      data-upload-state={uploadState !== 'is-default' ? uploadState : undefined}
      uploadConfig={uploadConfig}
      uploadCallbacks={uploadCallbacks}
    />
  )
}
