import {announce} from '@github-ui/aria-live'
import {SkeletonText} from '@github-ui/code-view-shared/components/Skeleton'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {useSuspenseQuery} from '@github-ui/react-query'
import {AlertFillIcon, CopyIcon, StarIcon, TagIcon, TriangleDownIcon, VerifiedIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Breadcrumbs, Heading, IconButton, Link, Stack, Truncate} from '@primer/react'
import {type ReactNode, Suspense, useEffect, useState} from 'react'

import {fetchMarketplaceActionDetail} from '../Workflows/Marketplace'
import {ActionLogo} from './ActionLogo'
import styles from './MarketplaceItemDetail.module.css'
import type {MarketplaceItem} from './types'

interface MarketplaceItemDetailProps {
  src?: string
  item: MarketplaceItem
  onBack: () => void
}

function detailUrlFor(src: string | undefined, id: number): string | undefined {
  if (!src) return undefined
  return src.replace(/marketplace-search(?:\?.*)?$/, `marketplace/${id}`)
}

function marketplaceDetailQueryOptions(detailUrl: string) {
  return {
    queryKey: ['editor-actions-marketplace-detail', detailUrl],
    queryFn: () => fetchMarketplaceActionDetail(detailUrl),
    staleTime: Infinity,
  }
}

function SnippetRegion({label, children}: {label: string; children: ReactNode}) {
  return (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- scrollable region requires tabIndex for keyboard access
    <div className={styles.SnippetRegion} role="region" aria-label={`Code snippet for ${label}`} tabIndex={0}>
      {children}
    </div>
  )
}

function MarketplaceLatestVersion({detailUrl}: {detailUrl: string}) {
  const {data: detail} = useSuspenseQuery(marketplaceDetailQueryOptions(detailUrl))
  return (
    <Stack direction="horizontal" gap="condensed" align="center">
      <TagIcon className="fgColor-muted" />
      <span className="text-small fgColor-muted">{detail.latestVersion}</span>
    </Stack>
  )
}

function MarketplaceLatestVersionFallback() {
  return (
    <Stack direction="horizontal" gap="condensed" align="center">
      <TagIcon className="fgColor-muted" />
      <SkeletonText width={40} />
    </Stack>
  )
}

function MarketplaceItemSnippet({name, detailUrl}: {name: string; detailUrl: string}) {
  const {data: detail} = useSuspenseQuery(marketplaceDetailQueryOptions(detailUrl))
  const [selectedVersion, setSelectedVersion] = useState<string | null>(null)

  const releases = detail.releases ?? []
  const effectiveVersion = selectedVersion ?? detail.latestVersion ?? null
  const selectedSnippet = releases.find(release => release.version === effectiveVersion)?.snippet ?? ''

  return (
    <>
      <Stack
        direction="horizontal"
        justify="space-between"
        align="center"
        padding="condensed"
        className={styles.TerminalHeader}
      >
        <ActionMenu>
          <ActionMenu.Button trailingAction={TriangleDownIcon} variant="invisible">
            <span className="text-semibold">Version:</span> {effectiveVersion}
          </ActionMenu.Button>
          <ActionMenu.Overlay width="small">
            <ActionList selectionVariant="single">
              {releases.map(release => (
                <ActionList.Item
                  key={release.version}
                  selected={release.version === effectiveVersion}
                  onSelect={() => setSelectedVersion(release.version)}
                >
                  {release.version}
                </ActionList.Item>
              ))}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>

        <CopyToClipboardButton
          ariaLabel="Copy snippet to clipboard"
          textToCopy={selectedSnippet}
          variant="invisible"
          size="small"
          disabled={!selectedSnippet}
        />
      </Stack>

      <SnippetRegion label={name}>
        <pre className={styles.Snippet}>{selectedSnippet}</pre>
      </SnippetRegion>
    </>
  )
}

function MarketplaceItemSnippetFallback({name}: {name: string}) {
  return (
    <>
      <Stack
        direction="horizontal"
        justify="space-between"
        align="center"
        padding="condensed"
        className={styles.TerminalHeader}
      >
        <SkeletonText width={120} />
        <IconButton icon={CopyIcon} aria-label="Copy snippet to clipboard" variant="invisible" size="small" disabled />
      </Stack>

      <SnippetRegion label={name}>
        <div className={styles.SnippetSkeleton} data-testid="marketplace-detail-snippet-skeleton">
          <SkeletonText width="80%" />
          <SkeletonText width="60%" />
          <SkeletonText width="70%" />
        </div>
      </SnippetRegion>
    </>
  )
}

function MarketplaceItemSnippetError() {
  useEffect(() => {
    announce("Couldn't load versions.", {assertive: true})
  }, [])

  return (
    <>
      <div className={styles.SnippetError} data-testid="marketplace-detail-error">
        <AlertFillIcon />
        <span>Couldn&rsquo;t load snippet.</span>
      </div>
    </>
  )
}

export function MarketplaceItemDetail({src, item, onBack}: MarketplaceItemDetailProps) {
  const detailUrl = detailUrlFor(src, item.id)

  return (
    <Stack gap="normal">
      <Breadcrumbs>
        <Breadcrumbs.Item as="button" type="button" className={styles.BackCrumb} onClick={onBack}>
          Marketplace
        </Breadcrumbs.Item>
        <Breadcrumbs.Item as="span" selected>
          <Truncate maxWidth="150px" title={item.name} inline>
            {item.name}
          </Truncate>
        </Breadcrumbs.Item>
      </Breadcrumbs>

      <Stack direction="horizontal" gap="normal" align="start">
        <ActionLogo action={item} className={styles.Logo} />
        <Stack.Item grow>
          <Stack gap="condensed">
            <Heading as="h2" variant="small">
              {item.name}
            </Heading>

            <Stack direction="horizontal" wrap="wrap" gap="condensed" align="center">
              {item.ownerLogin && (
                <Stack direction="horizontal" gap="condensed" align="center">
                  <span className="text-small fgColor-muted">
                    by <span>{item.ownerLogin}</span>
                  </span>
                  {item.verifiedOwner && <VerifiedIcon className="fgColor-accent" />}
                </Stack>
              )}

              {detailUrl && (
                <ErrorBoundary key={detailUrl} fallback={null} boundaryName="marketplace-item-latest-version">
                  <Suspense fallback={<MarketplaceLatestVersionFallback />}>
                    <MarketplaceLatestVersion detailUrl={detailUrl} />
                  </Suspense>
                </ErrorBoundary>
              )}

              <Stack direction="horizontal" gap="condensed" align="center">
                <StarIcon className="fgColor-muted" />
                <span className="text-small fgColor-muted">{item.stargazerCount}</span>
              </Stack>
            </Stack>
          </Stack>
        </Stack.Item>
      </Stack>

      <div className="fgColor-muted">{item.description}</div>

      <div className="text-small">
        <Link href={item.marketplacePath} target="_blank" rel="noopener noreferrer">
          View full Marketplace listing
        </Link>
      </div>

      <Stack gap="condensed" className="border-top borderColor-muted pt-3">
        <Heading as="h3" variant="small">
          Installation
        </Heading>
        <div className="text-small fgColor-muted">
          Copy and paste the following snippet into your <span className={styles.Mono}>.yml</span> file.
        </div>
      </Stack>

      <div className={styles.Terminal}>
        {detailUrl ? (
          <ErrorBoundary
            key={detailUrl}
            fallback={<MarketplaceItemSnippetError />}
            boundaryName="marketplace-item-snippet"
          >
            <Suspense fallback={<MarketplaceItemSnippetFallback name={item.name} />}>
              <MarketplaceItemSnippet key={detailUrl} name={item.name} detailUrl={detailUrl} />
            </Suspense>
          </ErrorBoundary>
        ) : (
          <MarketplaceItemSnippetError />
        )}
      </div>
    </Stack>
  )
}
