import type {EditorInfo} from '@github-ui/code-view-types'
import {devContainerEditor} from '@github-ui/codemirror-editors/json/devcontainer/editor'
import {dependabotEditor} from '@github-ui/codemirror-editors/yaml/dependabot/editor'
import {githubModelsEditor} from '@github-ui/codemirror-editors/yaml/github-models/editor'
import {triageAgentEditor} from '@github-ui/codemirror-editors/yaml/triage-agent/editor'
import {workflowEditor} from '@github-ui/codemirror-editors/yaml/workflow/editor'

const VALID_DEVCONTAINER_PATH_GLOB =
  /\.devcontainer(?:(?:\/(?:[\w\-.'"][\w\-.'"\s]{0,62}[\w\-.'"]|[\w\-.'"]))?\/devcontainer)?\.json/

const isDevContainerEditorEnabled = (devContainerEditorEnabled: boolean, filePath: string) => {
  return devContainerEditorEnabled && VALID_DEVCONTAINER_PATH_GLOB.test(filePath)
}

export const isDependabotEditorEnabled = (dependabotEditorEnabled: boolean, filePath: string) => {
  return dependabotEditorEnabled && /^(\.github\/dependabot\.(yaml|yml))/i.test(filePath)
}

export const isGitHubModelsEditorEnabled = (filePath: string) => {
  return /(\.prompt\.(yaml|yml))$/i.test(filePath)
}

export const isStackEditorEnabled = (stacksEnabled: boolean, filePath: string) => {
  return stacksEnabled && /^(\.github\/stacks\/stack\.(yaml|yml))/i.test(filePath)
}

export const isTriageAgentEditorEnabled = (
  triageAgentEditorEnabled: boolean,
  filePath: string,
  configPath?: string,
) => {
  return triageAgentEditorEnabled && !!configPath && filePath.toLowerCase() === configPath.toLowerCase()
}

export const isWorkflowEditorEnabled = (actionsEnabled: boolean, filePath: string) => {
  return actionsEnabled && /^(\.github\/(workflows|workflows-lab)\/.+\.(yaml|yml))/i.test(filePath)
}

export const isActionEditorEnabled = (actionsEnabled: boolean, filePath: string) => {
  // Match action.yml/action.yaml at repo root or in any subdirectory
  // The file must be named exactly "action.yml" or "action.yaml" (not "my-action.yml")
  // Exclude .github/workflows paths - those are handled by workflow editor
  if (!actionsEnabled) {
    return false
  }
  // Don't match action.yml in workflow directories - workflow editor takes precedence
  if (/^\.github\/(workflows|workflows-lab)\//i.test(filePath)) {
    return false
  }
  return /(^|\/)action\.(yaml|yml)$/i.test(filePath)
}

export function getEditorEnablements(
  editorInfo: EditorInfo,
  completeFilePath: string,
  configPaths?: Record<string, string>,
) {
  const workflowEditorEnabled = isWorkflowEditorEnabled(editorInfo.actionsEnabled, completeFilePath)
  const actionEditorEnabled = isActionEditorEnabled(editorInfo.actionsEnabled, completeFilePath)
  const dependabotEditorEnabled = isDependabotEditorEnabled(editorInfo.dependabotEditorEnabled, completeFilePath)
  const githubModelsEditorEnabled = isGitHubModelsEditorEnabled(completeFilePath)
  const devContainerEditorEnabled = isDevContainerEditorEnabled(editorInfo.devcontainerEditorEnabled, completeFilePath)
  const triageAgentEditorEnabled = isTriageAgentEditorEnabled(
    editorInfo.triageAgentEditorEnabled,
    completeFilePath,
    configPaths?.triageAgent,
  )

  return {
    workflowEditorEnabled,
    actionEditorEnabled,
    dependabotEditorEnabled,
    devContainerEditorEnabled,
    githubModelsEditorEnabled,
    triageAgentEditorEnabled,
  }
}

export function getEditorExtensions(
  editorInfo: EditorInfo,
  completeFilePath: string,
  configPaths?: Record<string, string>,
) {
  const enabledEditors = getEditorEnablements(editorInfo, completeFilePath, configPaths)
  const {
    workflowEditorEnabled,
    actionEditorEnabled,
    dependabotEditorEnabled,
    devContainerEditorEnabled,
    githubModelsEditorEnabled,
    triageAgentEditorEnabled,
  } = enabledEditors

  let editorExtensions = undefined

  if (workflowEditorEnabled) {
    editorExtensions = workflowEditor('workflow.yaml')
  } else if (actionEditorEnabled) {
    editorExtensions = workflowEditor('action.yaml')
  } else if (dependabotEditorEnabled) {
    editorExtensions = dependabotEditor()
  } else if (devContainerEditorEnabled) {
    editorExtensions = devContainerEditor()
  } else if (githubModelsEditorEnabled) {
    editorExtensions = githubModelsEditor()
  } else if (triageAgentEditorEnabled) {
    editorExtensions = triageAgentEditor()
  }

  return editorExtensions
}
