import {type PathFunction, encodePart} from '@github-ui/paths'
// eslint-disable-next-line import/no-nodejs-modules
import {Buffer} from 'buffer'

export const promotePushProtectionBypassPath: PathFunction<{
  ownerDisplayLogin: string
  repoName: string
  ksuid: string
}> = ({ownerDisplayLogin, repoName, ksuid}) =>
  `/${encodePart(ownerDisplayLogin)}/${encodePart(repoName)}/security/secret-scanning/unblock-secret/${ksuid}`

export const requestPushProtectionBypassPath: PathFunction<{
  ownerDisplayLogin: string
  repoName: string
  ksuid: string
  ruleSuiteId: number
}> = ({ownerDisplayLogin, repoName, ksuid, ruleSuiteId}) => {
  const hashId = Buffer.from(encodeURI(`secret_scanning-${ruleSuiteId}-${ksuid}`)).toString('base64')
  return `/${encodePart(ownerDisplayLogin)}/${encodePart(repoName)}/secret_scanning/exemptions/new/${hashId}`
}
