import type {UploadState} from '@github-ui/batch-upload'
import type {EditorUploadEvent} from '@github-ui/file-attachment-editor'
import {FileAttachmentEditor} from '@github-ui/file-attachment-editor'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useCSRFToken} from '@github-ui/use-csrf-token'
import {MarkdownIcon} from '@primer/octicons-react'
import {Spinner} from '@primer/react'
import {Tooltip} from '@primer/react/next'
import React from 'react'

import {codeViewLayoutRoute} from '../../routes/code-view-layout-route'
import {buildExtensionsSentence} from '../../utilities/file-extensions'
import styles from './FileUpload.module.css'

interface FileUploadProps {
  allowedExtensions: string[]
  allowDragAndDrop: boolean
  markdownDocsUrl?: string
  repositoryId?: string | number
  uploadPath: string
  stickyFooter?: boolean
  disabled?: boolean
  onEditorUpload: (event: EditorUploadEvent) => void
}

export function FileUpload({
  isDataRouter,
  ...props
}: React.PropsWithChildren<FileUploadProps> & {isDataRouter?: boolean}) {
  if (isDataRouter) {
    return <FileUploadWithQuery {...props} />
  }

  return <FileUploadWithRoutePayload {...props} />
}

function FileUploadWithQuery(props: React.PropsWithChildren<FileUploadProps>) {
  const {
    data: {uploadToken},
  } = useRouteQuery(codeViewLayoutRoute, 'mainQuery')

  if (!uploadToken) return null

  return <FileUploadInternal {...props} uploadToken={uploadToken} />
}

export function FileUploadWithRoutePayload(props: React.PropsWithChildren<FileUploadProps>) {
  const uploadToken = useCSRFToken(props.uploadPath, 'post')

  return <FileUploadInternal {...props} uploadToken={uploadToken || ''} />
}

function FileUploadInternal({
  allowedExtensions,
  allowDragAndDrop,
  children,
  markdownDocsUrl,
  repositoryId,
  uploadPath,
  stickyFooter = false,
  disabled = false,
  uploadToken,
  onEditorUpload,
}: React.PropsWithChildren<FileUploadProps> & {uploadToken: string}) {
  const friendlyExtensionSentence = buildExtensionsSentence(allowedExtensions)
  const [isFocused, setIsFocused] = React.useState(false)
  const [uploadState, setUploadState] = React.useState<UploadState>('is-default')

  const stateClass = uploadState !== 'is-default' ? uploadState : ''

  return (
    <FileAttachmentEditor
      inputId="blob-dragged-file-input"
      policyUrl={uploadPath}
      csrfToken={uploadToken}
      repositoryId={repositoryId != null ? String(repositoryId) : undefined}
      uploadContainerType="blob"
      uploadContainerId={repositoryId != null ? String(repositoryId) : undefined}
      onEditorUpload={onEditorUpload}
      onUploadStateChange={state => {
        setUploadState(state)
      }}
      className={`is-default file-editor-upload react-file-upload ${stateClass}`}
      preventAccidentalDrops
    >
      {children}
      <label
        hidden={disabled}
        className={`text-normal drag-and-drop hx_drag-and-drop d-flex flex-justify-between border-0 border-top border-dashed position-relative ${
          stickyFooter ? 'position-sm-sticky bottom-sm-0' : ''
        }  ${isFocused ? 'file-input-focused' : ''}`}
      >
        <input
          id="blob-dragged-file-input"
          type={'file'}
          accept={allowedExtensions.join(',')}
          multiple
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          className="manual-file-chooser manual-file-chooser-transparent top-0 right-0 bottom-0 left-0 width-full ml-0 form-control rounded-top-0"
        />
        <span
          className="color-bg-subtle position-absolute top-0 left-0 rounded-bottom-2 width-full height-full"
          style={{pointerEvents: 'none'}}
        />
        <span className="position-relative pr-2" style={{pointerEvents: 'none'}}>
          {uploadState === 'is-default' && (
            <span className="default">
              Attach files by {allowDragAndDrop ? 'dragging & dropping, ' : ''}selecting or pasting them.
            </span>
          )}
          {uploadState === 'is-uploading' && (
            <span className="loading">
              <Spinner size={'small'} className={styles.Spinner} />
              <span>Uploading your files…</span>
            </span>
          )}
          {uploadState === 'is-bad-file' && (
            <span className="error bad-file">
              We don’t support that file type.
              <span className="drag-and-drop-error-info">
                <span className="btn-link">Try again</span> with a {friendlyExtensionSentence}.
              </span>
            </span>
          )}

          {uploadState === 'is-bad-permissions' && (
            <span className="error bad-permissions">
              Attaching documents requires write permission to this repository.
              <span className="drag-and-drop-error-info">
                <span className="btn-link">Try again</span> with a {friendlyExtensionSentence}.
              </span>
            </span>
          )}

          {uploadState === 'is-repository-required' && (
            <span className="error repository-required">
              We don’t support that file type.
              <span className="drag-and-drop-error-info">
                <span className="btn-link">Try again</span> with a {friendlyExtensionSentence}.
              </span>
            </span>
          )}

          {uploadState === 'is-too-big' && (
            <span className="error too-big">
              Yowza that&apos;s a big file.{' '}
              <span className="drag-and-drop-error-info">
                {' '}
                <span className="btn-link">Try again</span> with a file size less than 10MB.
              </span>
            </span>
          )}

          {uploadState === 'is-empty' && (
            <span className="error empty">
              This file is empty.
              <span className="drag-and-drop-error-info">
                <span className="btn-link">Try again</span> with a file that’s not empty.
              </span>
            </span>
          )}

          {uploadState === 'is-hidden-file' && (
            <span className="error hidden-file">
              This file is hidden.
              <span className="drag-and-drop-error-info">
                <span className="btn-link">Try again</span> with another file.
              </span>
            </span>
          )}

          {uploadState === 'is-failed' && (
            <span className="error failed-request">
              Something went really wrong, and we can’t process that file.
              <span className="drag-and-drop-error-info">
                <span className="btn-link">Try again.</span>
              </span>
            </span>
          )}
        </span>

        <Tooltip id="blob-markdown-help" text="Styling with Markdown is supported" direction="nw">
          <a
            aria-labelledby="blob-markdown-help"
            className="Link--muted position-relative d-inline"
            href={markdownDocsUrl}
            target="_blank"
            data-ga-click="Markdown Toolbar, click, help"
            rel="noreferrer"
          >
            <MarkdownIcon verticalAlign="text-bottom" />
          </a>
        </Tooltip>
      </label>
    </FileAttachmentEditor>
  )
}
