import {isFeatureEnabled} from '@github-ui/feature-flags'
// eslint-disable-next-line no-restricted-imports -- existing usage pending feature flag cleanup
import {IncludeFragment} from '@github-ui/include-fragment-react'
import {useQueryClient} from '@github-ui/react-query'
import {useDebounce} from '@github-ui/use-debounce'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {Spinner} from '@primer/react'
import {useCallback, useState} from 'react'

import {MarketplacePanel} from '../Marketplace/MarketplacePanel'
import type {FeaturedCategory, MarketplaceActionDetail} from '../Marketplace/types'
import {marketplaceQueryKey, useMarketplaceData} from '../Marketplace/use-marketplace-data'
import styles from './Marketplace.module.css'

interface WorkflowMarketplaceProps {
  src?: string
}

export async function fetchMarketplaceActionDetail(url: string): Promise<MarketplaceActionDetail> {
  const response = await verifiedFetchJSON(url)

  if (!response?.ok) {
    throw new Error(`Failed to fetch marketplace action detail: ${response?.status}`)
  }

  return (await response.json()) as MarketplaceActionDetail
}

export function WorkflowMarketplace({src}: WorkflowMarketplaceProps) {
  import('@github-ui/editor-actions-sidebar')

  const reactSidebarEnabled = isFeatureEnabled('react_editor_actions_sidebar')

  const [searchInput, setSearchInput] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<FeaturedCategory | null>(null)
  const [page, setPage] = useState(1)
  const debouncedSetSearchQuery = useDebounce((value: string) => setSearchQuery(value), 250)
  const queryClient = useQueryClient()

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchInput(value)
      // reset pagination on search change
      setPage(1)

      const trimmed = value.trim()

      // when the input is cleared, skip the debounce and restore the cached results immediately
      if (trimmed === '') {
        debouncedSetSearchQuery.cancel()
        setSearchQuery('')
        return
      }

      // skip the debounce if this term's results are already cached,
      if (queryClient.getQueryData(marketplaceQueryKey(src, trimmed, selectedCategory?.slug ?? '', 1))) {
        debouncedSetSearchQuery.cancel()
        setSearchQuery(value)
        return
      }

      debouncedSetSearchQuery(value)
    },
    [debouncedSetSearchQuery, queryClient, selectedCategory, src],
  )

  const handleCategorySelect = useCallback(
    (category: FeaturedCategory) => {
      debouncedSetSearchQuery.cancel()
      setSearchInput('')
      setSearchQuery('')
      setPage(1)
      setSelectedCategory(category)
    },
    [debouncedSetSearchQuery],
  )

  const handleCategoryClear = useCallback(() => {
    debouncedSetSearchQuery.cancel()
    setSearchInput('')
    setSearchQuery('')
    setPage(1)
    setSelectedCategory(null)
  }, [debouncedSetSearchQuery])

  const {data, isLoading, isFetching, isError} = useMarketplaceData({
    src,
    query: searchQuery,
    category: selectedCategory?.slug,
    page,
    enabled: reactSidebarEnabled,
  })

  // only force a loading state when entering a search from the initial featured list
  const enteringSearch = searchInput.trim() !== '' && searchQuery.trim() === ''

  // a background fetch while results remain visible
  const paginating = isFetching && !isLoading && !enteringSearch

  if (reactSidebarEnabled) {
    return (
      <MarketplacePanel
        src={src}
        items={data?.featuredActions}
        categories={data?.categories}
        loading={isLoading || enteringSearch}
        fetching={paginating}
        error={isError}
        pagination={data?.pagination}
        onPageChange={setPage}
        searchQuery={searchInput}
        onSearchChange={handleSearchChange}
        selectedCategory={selectedCategory}
        onCategorySelect={handleCategorySelect}
        onCategoryClear={handleCategoryClear}
      />
    )
  } else {
    return (
      <div className={styles.Box}>
        <remote-input
          param="query"
          src={src}
          aria-owns="js-workflow-editor-sidebar-content"
          class="tmp-mb-3 position-relative js-remoteinput"
        >
          <input
            type="text"
            form="marketplace-search"
            className="form-control input-block input-contrast"
            /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
            placeholder="Search Marketplace for Actions"
            /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
            aria-label="Search Marketplace for Actions"
          />
        </remote-input>
        <div id="js-workflow-editor-sidebar-content">
          <IncludeFragment src={src}>
            <Spinner className={styles.Spinner} />
          </IncludeFragment>
        </div>
      </div>
    )
  }
}
