import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

import type {FeaturedCategory, MarketplaceItem} from './types'

export interface Pagination {
  previousPage: number | null
  nextPage: number | null
}

interface MarketplaceData {
  featuredActions: MarketplaceItem[]
  categories: FeaturedCategory[]
  pagination: Pagination
}

// The default "featured" endpoint (no query) returns `{featuredActions, categories}`, while the
// search endpoint (with a `query`) returns `{results, categoryName, pagination, ...}`
interface FeaturedResponse {
  featuredActions?: MarketplaceItem[]
  categories?: FeaturedCategory[]
}

interface SearchResponse {
  results?: MarketplaceItem[]
  pagination?: Pagination
}

type MarketplaceResponse = FeaturedResponse & SearchResponse

interface UseMarketplaceDataOptions {
  src?: string
  query?: string
  category?: string
  page?: number
  enabled?: boolean
}

const EMPTY_PAGINATION: Pagination = {previousPage: null, nextPage: null}

async function fetchMarketplaceData(url: string): Promise<MarketplaceData> {
  const response = await verifiedFetchJSON(url)

  if (!response?.ok) {
    throw new Error(`Failed to fetch featured marketplace actions: ${response?.status}`)
  }

  const json = (await response.json()) as MarketplaceResponse

  return {
    featuredActions: json.results ?? json.featuredActions ?? [],
    categories: json.categories ?? [],
    pagination: json.pagination ?? EMPTY_PAGINATION,
  }
}

function searchUrlFor(src: string | undefined, query: string, category: string, page: number): string | undefined {
  if (!src) return undefined

  const trimmed = query.trim()
  const params = new URLSearchParams()
  if (trimmed) {
    params.set('query', trimmed)
  }
  if (category) {
    params.set('category', category)
  }
  if (page > 1) {
    params.set('page', String(page))
  }

  const queryString = params.toString()
  if (!queryString) return src

  const separator = src.includes('?') ? '&' : '?'
  return `${src}${separator}${queryString}`
}

export function marketplaceQueryKey(src: string | undefined, query: string, category: string, page: number) {
  return ['editor-actions-marketplace-search', src, query.trim(), category, page] as const
}

export function useMarketplaceData({
  src,
  query = '',
  category = '',
  page = 1,
  enabled = true,
}: UseMarketplaceDataOptions) {
  const url = searchUrlFor(src, query, category, page)
  const trimmedQuery = query.trim()

  // This hits a legacy marketplace JSON endpoint via `verifiedFetchJSON`, not a Protobuf-backed
  // service, so there is no schema to validate/decode responses against.
  // eslint-disable-next-line @github-ui/github-monorepo/require-query-persister, @github-ui/github-monorepo/require-query-schema
  return useQuery({
    queryKey: marketplaceQueryKey(src, trimmedQuery, category, page),
    queryFn: () => fetchMarketplaceData(searchUrlFor(src, trimmedQuery, category, page) ?? ''),
    enabled: enabled && !!url,
    staleTime: Infinity,
    // keep the previous results visible while refining a search or paging (prevents layout thrashing)
    placeholderData: (previousData, previousQuery) => {
      if (!previousQuery) return undefined

      const [, , previousQueryTerm, previousCategory, previousPage] = previousQuery.queryKey

      // retain previous results while refining within the same search term
      if (trimmedQuery && previousQueryTerm) return previousData

      // retain previous results while paging within the same term + category
      const samePage = previousPage === page
      if (!samePage && previousQueryTerm === trimmedQuery && previousCategory === category) {
        return previousData
      }

      return undefined
    },
  })
}
