import type {RootRule, Rule} from '../rule-util'

const filterRule: Rule = {
  description: 'GitHub search query — matching issues are skipped',
  single: ['string'],
}

const issueCreateRule: Rule = {
  description: 'Trigger on new issue creation',
  required: true,
  single: ['boolean'],
  rules: {
    filter: filterRule,
  },
}

const issueCommentRule: Rule = {
  description: 'Trigger retriage on @copilot mentions in comments (true/false)',
  required: true,
  single: ['boolean'],
}

const onRule: Rule = {
  description: 'Events that trigger the triage agent',
  required: true,
  rules: {
    'issue-create': issueCreateRule,
    'issue-comment': issueCommentRule,
  },
}

const actionAllowBlockRule: Rule = {
  description: 'Action permission with allowed/blocked value lists',
  required: true,
  rules: {
    allowed: {
      description: 'Permitted values (use ["*"] to allow all)',
      multipleValues: true,
      items: {single: ['string']},
    },
    blocked: {
      description: 'Blocked values (use ["*"] to block all)',
      multipleValues: true,
      items: {single: ['string']},
    },
  },
}

const addCommentRule: Rule = {
  description: 'Whether the agent posts a triage comment (true/false)',
  required: true,
  single: ['boolean'],
}

const allowedActionsRule: Rule = {
  description: 'Actions the triage agent is permitted to take (required)',
  required: true,
  // Can be ["*"] (array wildcard) OR an object with action keys
  rules: {
    'add-comment': addCommentRule,
    'add-labels': actionAllowBlockRule,
    'add-type': actionAllowBlockRule,
    'add-fields': actionAllowBlockRule,
  },
  // Accept arrays for the ["*"] wildcard shorthand
  items: {
    values: ['*'],
  },
  maxLength: 1,
}

export function getRootRule(): RootRule {
  return {
    rules: {
      on: onRule,
      'allowed-actions': allowedActionsRule,
    },
  }
}
